inputs.script:
let table = base.getTable("Emails");
let recordId = input.config().recordId;
let record = await table.selectRecordAsync(recordId);

if (!record) {
    throw new Error("No record found");
}

// Helper to sanitize for Slack
function sanitizeForSlack(text) {
    if (!text) return "";
    return text
        .replace(/\\/g, "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/\r?\n/g, "\n");
}

let payload = { recordId };

for (let field of table.fields) {
    let value = record.getCellValue(field.name);

    if (
        (field.name === "Latest Reply" || field.name === "Conversation History") &&
        typeof value === "string"
    ) {
        payload[field.name] = sanitizeForSlack(value);
    } else {
        payload[field.name] = value;
    }
}

let webhook = "https://hook.us1.make.com/REDACTED_PATH";
await fetch(webhook, {
    method: "POST",
    headers: { "Content-Type": "application/json; charset=utf-8" },
    body: JSON.stringify(payload)
});
